typedef int (*Operation)(int a, int b);

int add(int a, int b) { return a + b; }
int subtract(int a, int b) { return a - b; }

// Function taking a function pointer (Callback)
int execute(int x, int y, Operation op) {
    return op(x, y);
}

// Assignment
Operation math_op = add;
int result1 = math_op(10, 5); // Direct call: 15

// Dynamic selection and invocation
int result2 = execute(20, 7, subtract); // Callback: 13

// Direct pointer declaration (less readable)
int (*ptr_sub)(int, int) = subtract;
int result3 = (*ptr_sub)(5, 2); // 3
